#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y){
        ops.push_back({x,y});
        vector<int> res(n);
        for(int i=0;i<y;i++) res[i]=p[n-y+i];
        for(int i=y;i<n-x;i++) res[i]=p[x+i-y];
        for(int i=n-x;i<n;i++) res[i]=p[i-(n-x)];
        p=res;
    };

    for(int t=0;t<n-1 && (int)ops.size()<4*n;t++){
        int pos=-1;
        for(int i=t;i<n;i++) if(p[i]==t+1){pos=i;break;}
        if(pos==t) continue;
        // Move element from pos to position t
        // Step 1: move to position 0 using (0, n-pos) -- but x>=1
        // Use x=pos, y=n-1-pos if both >=1: element at pos goes to pos-pos+(n-1-pos)=n-1-pos
        // Use x=1, y=n-pos: element at pos goes to pos-1+n-pos=n-1. Need 1+n-pos<n => pos>1
        if(pos>0 && pos!=n-1){
            int x=pos, y=n-1-pos;
            if(x>=1&&y>=1&&x+y<n) doOp(x,y); // element goes to n-1-pos
            for(int i=0;i<n;i++) if(p[i]==t+1){pos=i;break;}
        }
        if(pos==t) continue;
        if(pos>0 && t<pos){
            int x=t, y=n-pos;
            if(x>=1&&y>=1&&x+y<n){ doOp(x,y); continue; }
        }
        // Brute force fallback
        for(int x=1;x<n;x++) for(int y=1;x+y<n;y++){
            int np; if(pos<x) np=n-x+pos; else if(pos<n-y) np=pos-x+y; else np=pos-(n-y);
            if(np==t){doOp(x,y);break;}
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
